// lxScript: return {plots:{name:[...]}, positions?:[...]}
const fast = ta.ema(close, 9), slow = ta.ema(close, 21);
return { plots: { 'EMA 9': fast, 'EMA 21': slow } };

const v = ta.vwap(bars);
const dev = ta.stdev(close, 20);
return { plots: { VWAP: v, 'VWAP+1σ': v.map((x,i)=>x+dev[i]), 'VWAP-1σ': v.map((x,i)=>x-dev[i]) } };

// Delta proxy: close position in range × volume, cumulated.
let acc = 0;
const cvd = bars.map(b => { const rng = b.h - b.l || 1e-9; acc += ((b.c - b.l) - (b.h - b.c)) / rng * b.v; return acc; });
return { pane: 'lower', plots: { CVD: cvd } };

const r = ta.rsi(close, 14), e = ta.ema(close, 34);
const pos = close.map((c,i) => c > e[i] && r[i] > 52 ? 1 : c < e[i] && r[i] < 48 ? -1 : 0);
return { plots: { 'EMA 34': e }, positions: pos };

const m = ta.sma(close, 20), sd = ta.stdev(close, 20);
const pos = close.map((c,i) => c < m[i] - 2*sd[i] ? 1 : c > m[i] + 2*sd[i] ? -1 : 0);
return { plots: { Mid: m, Upper: m.map((x,i)=>x+2*sd[i]), Lower: m.map((x,i)=>x-2*sd[i]) }, positions: pos };
